// Command contractsentinel is the 智能合约审计与形式化验证流水线 entry point.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

func main() {
	command := "demo"
	if len(os.Args) > 1 {
		command = os.Args[1]
	}
	switch command {
	case "demo":
		runDemo()
	case "version":
		fmt.Println("contractsentinel 0.1.0")
	case "help", "-h", "--help":
		usage()
	case "resolve":
		runResolve(os.Args[2:])
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Println("usage: contractsentinel <command> [arguments]")
	fmt.Println()
	fmt.Println("commands:")
	fmt.Println("  demo                        run the built-in audit demo")
	fmt.Println("  resolve <config-file>       resolve one JSON request (read from stdin)")
	fmt.Println("                              against offline routes; no network connections")
	fmt.Println("  version                     print the version")
	fmt.Println("  help                        show this help")
}

func runResolve(args []string) {
	if len(args) != 1 {
		fail(contractsentinel.Failure{Code: "invalid_usage",
			Reason: "usage: contractsentinel resolve <config-file>"})
	}

	configData, err := os.ReadFile(args[0])
	if err != nil {
		fail(contractsentinel.Failure{Code: "invalid_config",
			Reason: fmt.Sprintf("cannot read config file %q: %v", args[0], err)})
	}
	requestData, err := io.ReadAll(os.Stdin)
	if err != nil {
		fail(contractsentinel.Failure{Code: "invalid_request",
			Reason: fmt.Sprintf("cannot read request from stdin: %v", err)})
	}

	cfg, f := contractsentinel.ParseConfig(configData)
	if f != nil {
		fail(*f)
	}
	req, f := contractsentinel.ParseRequest(requestData)
	if f != nil {
		fail(*f)
	}
	resolution, f := contractsentinel.Resolve(cfg, req)
	if f != nil {
		fail(*f)
	}

	// HTML escaping is disabled so a raw query such as "a=1&b=2" is emitted
	// byte for byte instead of "&".
	enc := json.NewEncoder(os.Stdout)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(resolution); err != nil {
		fail(contractsentinel.Failure{Code: "internal_error", Reason: err.Error()})
	}
}

// fail prints the error as JSON to stderr and exits non-zero; stdout is left
// untouched so no partial result is observable on failure.
func fail(f contractsentinel.Failure) {
	enc := json.NewEncoder(os.Stderr)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(f)
	os.Exit(1)
}

func runDemo() {
	artifact := contractsentinel.Artifact{Name: "Vault", ABI: "[{\"name\":\"withdraw\"}]", Bytecode: "0x6080", Source: "Vault.sol"}
	rules := []contractsentinel.Rule{
		{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw"},
		{ID: "access-control", Kind: "static", Severity: "medium", Invariant: "owner-only-withdraw", RequiresABI: true},
		{ID: "invariant-preserved", Kind: "symbolic", Severity: "critical", Invariant: "balance-monotonic"},
	}
	invariants := map[string]bool{"no-reentrant-withdraw": false, "owner-only-withdraw": true, "balance-monotonic": false}
	findings, err := contractsentinel.Run(artifact, rules, invariants)
	if err != nil {
		fmt.Println("audit refused:", err)
		return
	}
	for _, finding := range findings {
		fmt.Printf("rule=%s severity=%s invariant=%s evidence=%s\n", finding.Rule, finding.Severity, finding.Invariant, finding.Evidence)
	}
	fmt.Printf("artifact=%s rules=%d findings=%d\n", artifact.Name, len(rules), len(findings))
}

package contractsentinel

import (
	"encoding/json"
	"strings"
	"testing"
)

func mustConfig(t *testing.T, src string) *Config {
	t.Helper()
	cfg, f := ParseConfig([]byte(src))
	if f != nil {
		t.Fatalf("unexpected config failure: %+v", f)
	}
	return cfg
}

func resolveJSON(t *testing.T, cfg *Config, reqSrc string) *Resolution {
	t.Helper()
	req, f := ParseRequest([]byte(reqSrc))
	if f != nil {
		t.Fatalf("unexpected request failure: %+v", f)
	}
	res, rf := Resolve(cfg, req)
	if rf != nil {
		t.Fatalf("unexpected resolve failure: %+v", rf)
	}
	return res
}

const sampleConfig = `{
  "routes": [
    {"id": "api",    "methods": ["GET"],        "pathPrefix": "/api",         "upstream": "http://api.internal/v1"},
    {"id": "api-v2", "methods": ["*"],          "pathPrefix": "/api/v2",      "upstream": "https://api.internal:8443/v2"},
    {"id": "orders", "methods": ["GET", "POST"],"pathPrefix": "/api/orders", "upstream": "http://orders.internal"},
    {"id": "root",   "methods": ["*"],          "pathPrefix": "/",            "upstream": "https://fallback.internal/base/"},
    {"id": "users",  "methods": ["GET"],        "pathPrefix": "/users",       "upstream": "http://users.internal/u"}
  ]
}`

func TestResolveBasicMatchAndJoin(t *testing.T) {
	cfg := mustConfig(t, sampleConfig)

	cases := []struct {
		name     string
		request  string
		routeID  string
		upstream string
	}{
		{
			name:     "exact prefix strips and joins base path",
			request:  `{"method":"GET","target":"/api"}`,
			routeID:  "api",
			upstream: "http://api.internal/v1/",
		},
		{
			name:     "prefix with deeper path joins on one slash",
			request:  `{"method":"GET","target":"/api/orders/42"}`,
			routeID:  "orders",
			upstream: "http://orders.internal/42",
		},
		{
			name:     "post also matches concrete method list",
			request:  `{"method":"POST","target":"/api/orders"}`,
			routeID:  "orders",
			upstream: "http://orders.internal/",
		},
		{
			name:     "longest prefix beats shorter on shared path",
			request:  `{"method":"GET","target":"/api/orders"}`,
			routeID:  "orders",
			upstream: "http://orders.internal/",
		},
		{
			name:     "upstream trailing base slash collapses to one",
			request:  `{"method":"GET","target":"/users/7/profile"}`,
			routeID:  "users",
			upstream: "http://users.internal/u/7/profile",
		},
		{
			name:     "root fallback keeps the full path",
			request:  `{"method":"GET","target":"/healthz"}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/healthz",
		},
		{
			name:     "root prefix with root target keeps junction slash",
			request:  `{"method":"GET","target":"/"}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/",
		},
		{
			name:     "wildcard method accepts unusual but legal method",
			request:  `{"method":"PROPFIND","target":"/api/v2/things/9"}`,
			routeID:  "api-v2",
			upstream: "https://api.internal:8443/v2/things/9",
		},
		{
			name:     "query string is ignored for matching but preserved verbatim",
			request:  `{"method":"GET","target":"/api/orders/1?expand=items&a=&a=2&b=%41%2f"}`,
			routeID:  "orders",
			upstream: "http://orders.internal/1?expand=items&a=&a=2&b=%41%2f",
		},
		{
			name:     "empty query string stays empty",
			request:  `{"method":"GET","target":"/api?"}`,
			routeID:  "api",
			upstream: "http://api.internal/v1/?",
		},
		{
			name:     "encoded path is matched raw and kept raw",
			request:  `{"method":"GET","target":"/users/a%20b%2Fc"}`,
			routeID:  "users",
			upstream: "http://users.internal/u/a%20b%2Fc",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res := resolveJSON(t, cfg, tc.request)
			if res.RouteID != tc.routeID {
				t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
			}
			if res.UpstreamURL != tc.upstream {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
			}
		})
	}
}

func TestResolveJunctionSlashCollapse(t *testing.T) {
	// Only the run where the base path's trailing slashes meet the
	// remainder's leading slashes is collapsed to a single slash; slashes,
	// dot segments and percent escapes anywhere else stay byte for byte.
	cfg := mustConfig(t, `{
	  "routes": [
	    {"id": "multi", "methods": ["GET"], "pathPrefix": "/api",  "upstream": "http://backend.internal/base///"},
	    {"id": "plain", "methods": ["GET"], "pathPrefix": "/v",    "upstream": "http://plain.internal/base"},
	    {"id": "nobase","methods": ["GET"], "pathPrefix": "/n",    "upstream": "http://nb.internal:8080"},
	    {"id": "root",  "methods": ["*"],   "pathPrefix": "/",     "upstream": "https://fallback.internal/base//"}
	  ]
	}`)

	cases := []struct {
		name     string
		request  string
		routeID  string
		upstream string
	}{
		{
			name:     "multi-slash base and remainder collapse at the junction",
			request:  `{"method":"GET","target":"/api//orders/7?a=1&a=&x=%2f+"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/orders/7?a=1&a=&x=%2f+",
		},
		{
			name:     "exact prefix with multi-slash base keeps one trailing slash",
			request:  `{"method":"GET","target":"/api"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/",
		},
		{
			name:     "remainder made only of slashes ends in the one junction slash",
			request:  `{"method":"GET","target":"/api///"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/",
		},
		{
			name:     "internal slashes and dot segments are left untouched",
			request:  `{"method":"GET","target":"/api//a//b/../c/"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/a//b/../c/",
		},
		{
			name:     "encoded slash right at the junction is data, not a junction slash",
			request:  `{"method":"GET","target":"/api/%2f/x"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/%2f/x",
		},
		{
			name:     "plain base with doubled leading remainder slashes collapses too",
			request:  `{"method":"GET","target":"/v//orders"}`,
			routeID:  "plain",
			upstream: "http://plain.internal/base/orders",
		},
		{
			name:     "upstream without a base path still joins with one slash",
			request:  `{"method":"GET","target":"/n//orders"}`,
			routeID:  "nobase",
			upstream: "http://nb.internal:8080/orders",
		},
		{
			name:     "upstream without a base path and exact prefix keeps the slash",
			request:  `{"method":"GET","target":"/n"}`,
			routeID:  "nobase",
			upstream: "http://nb.internal:8080/",
		},
		{
			name:     "root request keeps one junction slash over a multi-slash base",
			request:  `{"method":"GET","target":"/"}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/",
		},
		{
			name:     "root request leading multiple slashes follows the junction rule",
			request:  `{"method":"GET","target":"///healthz//"}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/healthz//",
		},
		{
			name:     "root internal slashes and dot segments are preserved",
			request:  `{"method":"GET","target":"/a//b/./c?z=1&&w="}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/a//b/./c?z=1&&w=",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res := resolveJSON(t, cfg, tc.request)
			if res.RouteID != tc.routeID {
				t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
			}
			if res.UpstreamURL != tc.upstream {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
			}
		})
	}
}

func TestResolveEncodedBasePathJoin(t *testing.T) {
	// The upstream base path is sliced out of the raw configured URL and the
	// remainder is appended with exactly one slash at the junction. Encoded
	// slashes (both cases), the userinfo encoding, the IPv6 brackets and the
	// port are content that must survive byte for byte; only the run where
	// the base path's trailing slashes meet the remainder's leading slashes
	// collapses. None of these routes defines queryTransforms, so the raw
	// query is preserved verbatim.
	cfg := mustConfig(t, `{
	  "routes": [
	    {"id": "enc",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f///"},
	    {"id": "dots", "methods": ["GET"], "pathPrefix": "/d",   "upstream": "http://dots.internal/a/./b/../c//"},
	    {"id": "root", "methods": ["*"],   "pathPrefix": "/",    "upstream": "https://root.internal/v%2f//base%2f///"}
	  ]
	}`)

	cases := []struct {
		name     string
		request  string
		routeID  string
		upstream string
	}{
		{
			name:     "encoded base path, userinfo, IPv6 and port survive the join",
			request:  `{"method":"GET","target":"/api//%2F/x//y/?a=1&a=&flag"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/%2F/x//y/?a=1&a=&flag",
		},
		{
			name:     "exact prefix keeps the encoded base path and one junction slash",
			request:  `{"method":"GET","target":"/api"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/",
		},
		{
			name:     "exact prefix with empty query keeps the bare question mark",
			request:  `{"method":"GET","target":"/api?"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/?",
		},
		{
			name:     "no query string stays distinct from an empty one",
			request:  `{"method":"GET","target":"/api/x"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/x",
		},
		{
			name:     "duplicate, empty and valueless parameters stay as written",
			request:  `{"method":"GET","target":"/api/p?b=1&b=&flag&b=2&c=%2f"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/p?b=1&b=&flag&b=2&c=%2f",
		},
		{
			name:     "root prefix with root target keeps encoded base and junction slash",
			request:  `{"method":"GET","target":"/"}`,
			routeID:  "root",
			upstream: "https://root.internal/v%2f//base%2f/",
		},
		{
			name:     "dot segments in the base path are never resolved",
			request:  `{"method":"GET","target":"/d/x"}`,
			routeID:  "dots",
			upstream: "http://dots.internal/a/./b/../c/x",
		},
		{
			name:     "exact prefix on a dot-segment base keeps the trailing junction slash",
			request:  `{"method":"GET","target":"/d"}`,
			routeID:  "dots",
			upstream: "http://dots.internal/a/./b/../c/",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res := resolveJSON(t, cfg, tc.request)
			if res.RouteID != tc.routeID {
				t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
			}
			if res.UpstreamURL != tc.upstream {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
			}
		})
	}
}

func TestInvalidConfigBracketedHostMustBeIPv6(t *testing.T) {
	// Square brackets mark an IP literal: their content must be a legal IPv6
	// address. A plain name, a bare IPv4 address, an empty pair or a malformed
	// IPv6 literal rejects the whole configuration as invalid_config with a
	// content reason that locates the route by 1-based position, its id and
	// the upstream field — never as a broken JSON document. The offending
	// route is rejected even when an earlier route is the one a request hits.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"name in brackets", "http://[not-an-ip]/v1"},
		{"bare ipv4 in brackets", "http://[127.0.0.1]:8080/v1"},
		{"empty brackets", "http://[]/v1"},
		{"too many colons", "http://[2001:db8:::1]/v1"},
		{"non hex group", "http://[gggg::1]/v1"},
		{"missing closing bracket", "http://[::1/v1"},
		{"empty percent encoded zone", "http://[fe80::1%25]/v1"},
		{"future version literal is not plain ipv6", "http://[v1.fe80::]/v1"},
		{"bad escape in literal", "http://[fe80::1%zz]/v1"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			_, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "IPv6"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			if strings.Contains(f.Reason, "not valid JSON") {
				t.Fatalf("a bad bracketed host is a content error, not a JSON syntax failure: %q", f.Reason)
			}
		})
	}

	// A bracketed host on a later route rejects the config even though the
	// request only matches the first, valid route.
	cfg, f := ParseConfig([]byte(`{"routes":[
	  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
	  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"http://[not-an-ip]/v1"}
	]}`))
	if f == nil {
		t.Fatal("expected the later route's bracketed-name upstream to reject the config")
	}
	if cfg != nil {
		t.Fatalf("a rejected config must not be returned, got %+v", cfg)
	}
}

func TestInvalidConfigBracketedHostShape(t *testing.T) {
	// One pair of square brackets must wrap the whole host: after the
	// closing ']' only the optional port (":" plus digits) may follow before
	// the base path. A valid first literal never legitimizes a repeated
	// bracket group, a stray ']', text between the address and the port, or
	// non-port bytes — with or without userinfo. Every such upstream rejects
	// the whole configuration as invalid_config with a content reason naming
	// the route position, its id and the upstream field, never as broken
	// JSON.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"repeated bracket group", "http://[::1][::2]/v1"},
		{"text and a stray closing bracket", "http://[::1]extra]/v1"},
		{"stray closing bracket", "http://[::1]]/v1"},
		{"repeated bracket group before a port", "http://[::1][::2]:8080/v1"},
		{"repeated bracket group after a port", "http://[::1]:8080[::2]/v1"},
		{"bare text after the closing bracket", "http://[::1]extra/v1"},
		{"digits after the bracket without a colon", "http://[::1]8080/v1"},
		{"non digit bytes in the port", "http://[::1]:80a/v1"},
		{"extra colon group in the port", "http://[::1]:80:80/v1"},
		{"userinfo with a repeated bracket group", "http://user:pw@[::1][::2]/v1"},
		{"encoded userinfo with text and a stray bracket", "https://user:p%40ss@[::1]extra]/v1"},
		{"encoded userinfo with junk after the port", "https://user:p%40ss@[::1]:8443x/v1"},
		{"userinfo with a second bracket group after the port", "http://u@[::1]:8080[::2]/v1"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			cfg, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "bracketed host", "IPv6"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			if strings.Contains(f.Reason, "not valid JSON") {
				t.Fatalf("a bad bracketed host shape is a content error, not a JSON syntax failure: %q", f.Reason)
			}
			if cfg != nil {
				t.Fatalf("a rejected config must not be returned, got %+v", cfg)
			}
		})
	}

	// The offending route may be one the request never hits: config
	// validation still fails up front (and hands back no config at all)
	// instead of letting the first, valid route resolve the request.
	for _, up := range []string{"http://[::1][::2]/v1", "http://[::1]extra]/v1"} {
		src := `{"routes":[
		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
		  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + up + `"}
		]}`
		cfg, f := ParseConfig([]byte(src))
		if f == nil || f.Code != "invalid_config" {
			t.Fatalf("upstream %q: got %+v, want invalid_config", up, f)
		}
		if cfg != nil {
			t.Fatalf("upstream %q: a rejected config must not be returned", up)
		}
	}
}

func TestResolveValidIPv6Upstreams(t *testing.T) {
	// Full, compressed and IPv4-tail forms are legal, as are a port,
	// percent-encoded userinfo and a percent-encoded zone. Validation must
	// not re-encode or otherwise alter the configured bytes: joining slices
	// the raw upstream, so every legal spelling reaches upstreamURL byte for
	// byte.
	cases := []struct {
		name     string
		upstream string
		target   string
		want     string
	}{
		{
			name:     "full form",
			upstream: "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b",
			target:   "/x",
			want:     "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b/x",
		},
		{
			name:     "compressed form",
			upstream: "http://[2001:db8::1]/b",
			target:   "/x",
			want:     "http://[2001:db8::1]/b/x",
		},
		{
			name:     "embedded ipv4 tail with port",
			upstream: "http://[::ffff:192.168.0.1]:8080/b",
			target:   "/x",
			want:     "http://[::ffff:192.168.0.1]:8080/b/x",
		},
		{
			name:     "userinfo, port and encoded base path",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f",
			target:   "/api/orders?a=1&a=",
			want:     "https://user:p%40ss@[2001:db8::1]:8443/v%2f/orders?a=1&a=",
		},
		{
			name:     "percent encoded zone keeps its original spelling",
			upstream: "https://[fe80::1%25eth0]/base",
			target:   "/x?z=1",
			want:     "https://[fe80::1%25eth0]/base/x?z=1",
		},
		{
			name:     "uppercase hex groups",
			upstream: "http://[2001:DB8::ABCD]/b",
			target:   "/x",
			want:     "http://[2001:DB8::ABCD]/b/x",
		},
		{
			name:     "userinfo, port, encoded base path and encoded slash query all stay verbatim",
			upstream: "https://user:p%40ss@[2001:DB8::1]:8443/v%2f",
			target:   "/api/x?q=%2f",
			want:     "https://user:p%40ss@[2001:DB8::1]:8443/v%2f/x?q=%2f",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			prefix := "/"
			if strings.HasPrefix(tc.target, "/api") {
				prefix = "/api"
			}
			src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"` + prefix +
				`","upstream":"` + tc.upstream + `"}]}`
			cfg := mustConfig(t, src)
			res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
			if res.RouteID != "r" {
				t.Errorf("routeId = %q, want r", res.RouteID)
			}
			if res.UpstreamURL != tc.want {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.want)
			}
		})
	}
}

