	hostPort, ok := upstreamHostPort(raw)
	if !ok {
		return nil // no scheme: the generic absolute-URL check reports this
	}
	// Brackets are validated separately; an ordinary reg-name (domain) or a
	// bare IPv4 host never carries a "::" and is untouched, including one
	// with a port ("example.com:8080", "127.0.0.1:8080") or with colons in
	// the userinfo or base path (both already sliced away).
	if strings.ContainsAny(hostPort, "[]") || !strings.Contains(hostPort, "::") {
		return nil
	}
	// A bare literal cannot carry a port (no brackets mark the boundary), so
	// a trailing ":digits" is part of the address — the rule refuses to guess
	// it as a port. netip never accepts that spelling anyway, but the bytes
	// are checked as the literal they were written.
