	if err != nil {
		return invalidUnbracketedIPv6Host(loc, id, hostPort)
	}
	addr, err := netip.ParseAddr(decoded)
	if err != nil || !addr.Is6() {
		return nil // not an IPv6 literal; the generic URL checks judge it
	}
	return invalidUnbracketedIPv6Host(loc, id, hostPort)
}

