package contractsentinel

import (
	"fmt"
	"testing"
)

func TestProbeBareIPv6(t *testing.T) {
	bad := []string{
		"http://2001:db8::1/base",
		"http://::1:8080/base",
		"http://::ffff:192.0.2.1/base",
		"http://2001:0db8:0000:0000:0000:0000:0000:0001/base",
		"http://2001:db8::1:8080/base",
		"http://fe80::1%25eth0/base",
		"http://u:p@2001:db8::1/base",
		"http://2001:db8::1:80/base",
	}
	good := []string{
		"http://[2001:db8::1]/base",
		"http://[::1]:8080/base",
		"http://[::ffff:192.0.2.1]/base",
		"http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b",
		"http://[fe80::1%25eth0]/base",
		"http://user:p%40ss@[2001:db8::1]:8443/b",
		"http://example.com/base",
		"http://example.com:8080/base",
		"http://127.0.0.1:8080/base",
		"http://127.0.0.1/base",
		"http://user:pass@example.com:8080/a:b",
	}
	for _, up := range bad {
		src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"` + up + `"}]}`
		_, f := ParseConfig([]byte(src))
		if f == nil {
			fmt.Printf("BAD-NOT-REJECTED %s\n", up)
			continue
		}
		fmt.Printf("REJECTED %-50s %s | %s\n", up, f.Code, f.Reason)
	}
	for _, up := range good {
		src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"` + up + `"}]}`
		_, f := ParseConfig([]byte(src))
		if f != nil {
			fmt.Printf("GOOD-WRONGLY-REJECTED %s -> %s\n", up, f.Reason)
		} else {
			fmt.Printf("ACCEPTED %s\n", up)
		}
	}
}
EOF
